#!/usr/bin/env node
/**
 * Copies the "Java by Building" lessons into src/content/course/.
 *
 *   node scripts/sync-course.mjs [path-to-java-by-building]
 *   npm run sync:course
 *
 * Source of truth is the course repository (lessons/index.json + each lesson README.md).
 * The generated files are committed so the Cloudflare build never needs the course repo.
 * Never edit src/content/course/ by hand: re-run this script instead.
 */
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, posix, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repoDir = resolve(process.argv[2] ?? process.env.COURSE_REPO ?? join(root, '..', 'java-by-building'));
const outDir = join(root, 'src', 'content', 'course');

const index = JSON.parse(readFileSync(join(repoDir, 'lessons', 'index.json'), 'utf8'));
const blob = `https://github.com/${index.repository}/blob/${index.branch}/`;
const tree = `https://github.com/${index.repository}/tree/${index.branch}/`;
const slugs = new Set(index.lessons.map((l) => l.slug));

/** Rewrites one relative markdown link target found in lessons/<slug>/README.md. */
function rewriteTarget(target, slug) {
  if (/^([a-z][a-z0-9+.-]*:|#|\/)/i.test(target)) return target; // absolute, anchor, mailto
  const [path, hash = ''] = target.split('#');
  const resolved = posix.normalize(posix.join('lessons', slug, path));
  const m = resolved.match(/^lessons\/([^/]+)\/README\.md$/);
  if (m && slugs.has(m[1])) return `/course/${m[1]}${hash ? '#' + hash : ''}`;
  const clean = resolved.replace(/\/$/, '');
  const isFile = /\.[A-Za-z0-9]+$/.test(clean);
  return (isFile ? blob : tree) + clean + (hash ? '#' + hash : '');
}

/** Rewrites links outside fenced code blocks and inline code spans. */
function rewriteLinks(body, slug) {
  let fenced = false;
  return body
    .split('\n')
    .map((line) => {
      if (/^\s*(```|~~~)/.test(line)) fenced = !fenced;
      if (fenced) return line;
      return line
        .split(/(`[^`]*`)/)
        .map((part) =>
          part.startsWith('`')
            ? part
            : part.replace(/\]\(([^)\s]+)\)/g, (_, t) => `](${rewriteTarget(t, slug)})`),
        )
        .join('');
    })
    .join('\n');
}

const q = (s) => JSON.stringify(s); // JSON strings are valid YAML

rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });

for (const lesson of index.lessons) {
  const raw = readFileSync(join(repoDir, lesson.readme), 'utf8').replace(/\r\n/g, '\n');
  const body = raw
    .replace(/^---\n[\s\S]*?\n---\n/, '') // front matter (metadata comes from index.json)
    .replace(/^\s*# .*\n/, ''); // page title is rendered by the layout
  const front = [
    '---',
    `title: ${q(lesson.title.replace(/^\d+\s*[—-]\s*/, ''))}`,
    `number: ${lesson.number}`,
    `week: ${lesson.week}`,
    `hours: ${lesson.hours}`,
    `level: ${q(lesson.level)}`,
    `milestone: ${q(lesson.milestone)}`,
    `objectives: ${q(lesson.objectives)}`,
    `folder: ${q(lesson.url)}`,
    '---',
    '',
    '<!-- Generated by scripts/sync-course.mjs from the java-by-building repository. Do not edit. -->',
    '',
  ].join('\n');
  writeFileSync(join(outDir, `${lesson.slug}.md`), front + rewriteLinks(body, lesson.slug));
}

console.log(`Synced ${index.lessons.length} lessons from ${repoDir} to ${outDir}`);
console.log(`Files: ${readdirSync(outDir).length}`);
